ProjectALife.DialogueShards["barks_misc_8"] = {
{"SEASON_WINTER","",{"Winter in Kentucky, you never know, sixty one day, ice the next","Short days - long nights, both too long","Wood pile's the only thing I check twice a day now","Firewood's currency now, I swear","Nobody tells you how loud a house gets when everybody's quiet and it's cold","Pipes burst every winter, used to complain - now I wish they were all I had to worry about","Daylight's gone by five, I hate winter evenings","Remember the March storm? We thought that was bad","Ice storms take the power every year, nothing to take now","Snow slows the dead down some, thank Christ","Nothing grows now, whatever we've got is whatever we've got","Long winter coming, we need to ration","Winter's here, and it's biting","Cold season, hard season","Winter, winter, winter, God help us","Days are short, nights are long","First frost, and the hard time begins"}},
{"SEASON_WINTER","reg=civilian,family,worker,rescue|tmp=seasoned",{"Hogs used to be killed this time of year, hams hung till spring","By January the whole county'll be one long hunger"}},
{"SEASON_WINTER","reg=civilian,family,worker,rescue|tmp=fresh|world=building",{"Christmas lights on that porch are still up, somebody's idea of hope"}},
{"SEASON_WINTER","reg=civilian,family,worker,rescue|tmp=fresh",{"Holidays, never thought I'd hate them - this year I do","Mama made fudge every December, I can still taste it"}},
{"SEASON_WINTER","reg=law,swat|world=road",{"Plow's been parked at the county garage since the Event - roads are on their own"}},
{"SEASON_WINTER","reg=law,swat|tmp=seasoned",{"Black ice on the overpass - quiet pileups, no rescuers"}},
{"SEASON_WINTER","reg=law,swat",{"Winter patrols are the worst, short sight lines, long nights"}},
{"SEASON_WINTER","reg=military,elite|tmp=veteran",{"Dry socks, spare gloves, a hat - don't walk into winter without them"}},
{"SEASON_WINTER","reg=military,elite",{"Cold kills quietly, we'll watch for it as hard as we watch for them","Winter operations, adjust gear, adjust plans"}},
{"SEASON_WINTER","reg=outlaw,raider,gang,club,crime,prison",{"Winter ain't gonna care who you are, it comes for everybody","Winter, ugh, cold and hungry, a bad combination"}},
{"SEASON_WINTER","reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{"Smells less when it's this cold, that's one thing"}},
{"SEASON_WINTER","reg=civilian,family,worker|mood=sad",{"Christmas, my kids' first Christmas without me, I hope"}},
{"SEASON_WINTER","reg=civilian,family,worker|tmp=seasoned|mood=calm",{"Need more firewood and blankets before it really hits"}},
{"SEEK_WARMTH","",{"I need to get warm - back in a minute","Heading for the fire","Gotta get inside before I lose my toes","Come on, let's get out of this wind","Fire first, then we think","There's smoke over there - people, maybe - warm, definitely","I'm going to stand somewhere warm and not talk for a while","Out of the wind, that's all I want","Right, enough - I'm finding a heater","If there's a wood stove in any of these houses, that's where I am"}},
{"SEEK_WARMTH","world=building",{"Going to find a stove or a fireplace - anything","Somewhere with a roof and a stove - come on"}},
{"SEEK_WARMTH","role=family_man,family_woman,law_sergeant,soldier_nco,swat_lead,raider_boss,gang_boss",{"Everybody to the fire - move"}},
{"SEEK_WARMTH","reg=civilian,family,worker,rescue|world=road",{"We'll sit this one out inside, the wind can have the street"}},
{"SEEK_WARMTH","reg=civilian,family,worker,rescue|tmp=fresh",{"My kids are not going to freeze on my watch - let's go"}},
{"SEEK_WARMTH","reg=civilian,family,worker,rescue|tmp=seasoned",{"Boil some water, find some blankets, let's get moving"}},
{"SEEK_WARMTH","role=rescue_medical,rescue_firefighter",{"Get these folks warm, move it"}},
{"SEEK_WARMTH","reg=military,elite|tmp=veteran",{"Break off, find a warm spot - don't sit on bare concrete"}},
{"SEEK_WARMTH","reg=military,elite",{"Back to the fire, low and quiet"}},
{"SEEK_WARMTH","reg=law,swat",{"Station's got a heater, if we can get in - move out"}},
{"SEEK_WARMTH","reg=law,swat|tmp=seasoned",{"Warm up, then back on patrol - ten minutes"}},
{"SEEK_WARMTH","reg=outlaw,raider,gang,club,crime,prison",{"Screw this wind, I'm going where it's warm"}},
{"SEEK_WARMTH","reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{"Anybody who's got a fire, I want a seat at it"}},
{"SEEK_WARMTH","reg=outlaw,raider,gang,club,crime,prison|tmp=predator|world=door",{"Warm up, then we go knock on doors"}},
{"SHIVER","",{"B-b-brr, can't stop shaking","My teeth won't quit chattering","Too c-cold, I can't even hold the straps","Shaking so hard I'm making noise - sorry","I'm f-fine, just a chill - just a little chill","It's in my bones now, can't shake it off","Hands won't close, hands won't close","I've got to get warm - right now - not later","Brrr, somebody get a fire going, please","Can't hold my gun straight, that's your problem too, you know","Tremors in the hands, not good for anything delicate","Brrr, brrr","I can't stop shaking","Teeth chattering, listen to them","Shaking like a leaf","Stop it, stop it, I can't stop","It's the cold, it's just the cold, it's just","My whole body's rattling","Shiver, shiver, shake, shake","Hold me, hold me, I'm freezing","Get closer, I need your warmth"}},
{"SHIVER","reg=civilian,family,worker,rescue|tmp=fresh",{"I can't feel my toes anymore - that's bad, right?","Is this what hypothermia feels like? I read about it once","Mom's chili - hot bath - both, I want both","Stop the shaking, stop the shaking, stop--"}},
{"SHIVER","reg=civilian,family,worker,rescue|tmp=seasoned",{"Nothing for it but a fire and a dry shirt"}},
{"SHIVER","reg=civilian,family,worker,rescue|role=rescue_medical,rescue_firefighter",{"Shivering means it's working, when it stops, that's when to worry"}},
{"SHIVER","role=rescue_medical",{"Shivers - normal - sit down, get warm, drink something hot"}},
{"SHIVER","reg=law,swat",{"I'm not wearing enough - my fault, my own fault","Cold, need to move, need to warm up"}},
{"SHIVER","reg=law,swat|tmp=fresh",{"Teeth are clacking - hold on a minute, sergeant"}},
{"SHIVER","reg=military,elite",{"Cold's got me, fire, then fall back in","Shivering, find cover, find warmth"}},
{"SHIVER","reg=military,elite|tmp=veteran",{"Shaking, not from fear, don't write that down"}},
{"SHIVER","reg=outlaw,raider,gang,club,crime,prison",{"Jesus, I'm shaking like a leaf - get me out of this wind","Brr, fuck, bastard cold"}},
{"SHIVER","reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{"My whole body's rattling - fire - now"}},
{"SHIVER","reg=civilian,family,worker|tmp=fresh|mood=fear",{"I'm cold, but that's not all of it... I can't stop shaking"}},
{"SHIVER","reg=civilian,family,worker|tmp=seasoned|mood=calm",{"Shivering means you're alive, keep it going"}},
{"SHIVER","reg=civilian,family,worker|mood=funny",{"I'm shaking like a dog at the vet"}},
{"SICK_COMPLAINT","",{"I think I'm coming down with something","Throat's scratchy, that's how it starts","Head's all stuffed up, great timing, world","Got a tickle in my chest I don't like","Feels like a cold, just a cold - I hope","Ache all over, probably the weather - probably","Not a bite, before anybody asks, just a cold","It's a cold. No bite, no scratch. I've checked","I feel hot and cold at the same time, not a good sign","Eyes burning, nose running - perfect","Swallowing hurts, can't be good"}},
{"SICK_COMPLAINT","reg=civilian,family,worker,rescue|tmp=fresh",{"I'm sick - plain sick - don't panic, nobody panic","If I sound terrible, it's because I do - stay back a bit"}},
{"SICK_COMPLAINT","reg=civilian,family,worker,rescue|tmp=seasoned",{"Caught it sleeping on that cold floor, I'd bet"}},
{"SICK_COMPLAINT","reg=civilian,family,worker,rescue",{"Grandma would've had me in bed with a hot water bottle by now"}},
{"SICK_COMPLAINT","role=rescue_medical",{"Doc's orders: rest - Doc's got no orders out here","Running a low fever, I know the signs, not infected, just ill"}},
{"SICK_COMPLAINT","reg=law,swat",{"Under the weather - shouldn't be on the line, but who's replacing me?"}},
{"SICK_COMPLAINT","reg=law,swat|tmp=seasoned",{"Coming down with a cold, won't slow me down - much"}},
{"SICK_COMPLAINT","reg=military,elite",{"Feeling poorly, will report if it worsens"}},
{"SICK_COMPLAINT","reg=military,elite|tmp=veteran",{"Fever - stay upwind and keep your hands to yourself"}},
{"SICK_COMPLAINT","reg=outlaw,raider,gang,club,crime,prison",{"Great, sick on top of everything else","Nose is leaking like a busted pipe, nobody say anything"}},
{"SICK_COMPLAINT","reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{"Don't look at me like that, I'm sick, not dead"}},
{"SICK_RECOVERED","",{"Nose is clear, first real breath in days","Think the cold's finally gone","Feeling like a person again","Head's clear - throat's fine, I'd forgotten what that was like","Fever broke, honest to God, I feel new","No more cough, thank you, whoever's listening","Better, finally... mostly, anyway","Back to a hundred percent - maybe ninety - ninety-five"}},
{"SICK_RECOVERED","reg=civilian,family,worker,rescue",{"Slept it off, thank goodness for small mercies"}},
{"SICK_RECOVERED","reg=civilian,family,worker,rescue|tmp=seasoned",{"Cold's gone, let's not talk about how I sounded"}},
{"SICK_RECOVERED","reg=law,swat",{"Fit for duty - mostly"}},
{"SICK_RECOVERED","reg=military,elite",{"Recovered - back on the roster"}},
{"SICK_RECOVERED","reg=outlaw,raider,gang,club,crime,prison",{"Finally, no more hacking in my own ear"}},
{"SICK_RECOVERED","reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{"Cold's behind me, anybody else gets sick, it wasn't me"}},
{"SMOKE_END","reg=civilian,family,worker,rescue",{"That's better, that settles me"}},
{"SMOKE_END","reg=law",{"Back to it"}},
{"SMOKE_END","reg=military",{"Break's over"}},
{"SMOKE_END","reg=outlaw,raider,gang,club,crime,prison",{"Alright, back on your feet"}},
{"SMOKE_START","reg=civilian,family,worker,rescue",{"Don't tell anyone, I'm having one cigarette"}},
{"SMOKE_START","reg=law",{"Taking a smoke - two minutes"}},
{"SMOKE_START","reg=military",{"Smoke break"}},
{"SMOKE_START","reg=outlaw,raider,gang,club,crime,prison",{"Light me up"}},
{"SNEEZE","",{"Achoo","Ah-CHOO - sorry","Hah-- choo!","Excuse me","Pardon me","Ahchoo! Ugh","Huh-- HAH-choo","Hhh-- hah-TCHOO","Sorry, dust - or something","Sorry, sorry, it's the cold","Ugh, there goes my nose again","That one came out of nowhere","Achoo! Don't look at me like that","Bless me, nobody else will","Hah-choo! Oh, that hurt my head","Ah-- ah-- ahCHOO - great, now my eyes are watering","Sorry, tickle in the nose - again"}},
{"SNEEZE","reg=civilian,family,worker,rescue",{"Mom always said three sneezes means company, I hope not"}},
{"SNEEZE","reg=law,swat",{"Sorry - allergies, not a cold - allergies"}},
{"SNEEZE","reg=military,elite",{"Cover your mouth - sorry, that was me"}},
{"SNEEZE","reg=military,elite|tmp=veteran",{"Sneeze like that and they'll hear us a block away - my bad"}},
{"SNEEZE","reg=outlaw,raider,gang,club,crime,prison",{"Damn it - Achoo, nobody say a word"}},
{"SNEEZE","reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{"Bless me, you bastards"}},
{"SNEEZE","reg=civilian,family,worker,rescue|tmp=fresh",{"Gesundheit, somebody say it - come on"}},
{"SNOW_FALLING","",{"Snow, well, that settles that","It's snowing, of course it is","I don't need snow on top of everything else","Snow covers everything - even this","Quiet snow - almost peaceful - almost","Tracks are going to show in this - mind your feet","Big flakes - wet ones - that sticks","Cold and snowing, could be worse, could be raining","White all over - hide a body in a drift and nobody'd know till spring","Hear that? Nothing, snow eats the sound","Flakes in my eyelashes, cold, but it's pretty","Snow... I almost want to laugh","It's snowing, it's actually snowing","Flakes, soft ones, big ones, falling slow","Everything's going white","Snow's sticking, it's already sticking","Quiet, snow makes everything quiet","First snow, and it comes now","Flurries, just flurries, but they're pretty","My eyelashes have snow on them","Snow in my hair, snow on my nose, snow down my neck","Tracks are going to show up in this, careful"}},
{"SNOW_FALLING","reg=civilian,family,worker,rescue",{"First snow of the year, used to be a holiday around here"}},
{"SNOW_FALLING","reg=civilian,family,worker,rescue|tmp=fresh",{"My kids would have loved this - snow day, school closed","Hold out your tongue, come on, nobody's watching"}},
{"SNOW_FALLING","reg=civilian,family,worker,rescue|tmp=seasoned",{"First one always feels like a gift, today I'm not so sure","Snow in Kentucky, you can set your watch by the ice that follows","Looks like the March storm all over again - buried everything"}},
{"SNOW_FALLING","reg=law,swat|world=road",{"Roads will be ice by dark - drive slow, not that anybody's driving"}},
{"SNOW_FALLING","reg=law,swat|tmp=seasoned",{"Fresh snow shows every footprint - ours too"}},
{"SNOW_FALLING","reg=military,elite",{"Snow shows tracks - watch the trail you leave","Snow, we stick out like sore thumbs in this gear"}},
{"SNOW_FALLING","reg=military,elite|tmp=veteran",{"Snow dampens sound, good for us, good for them"}},
{"SNOW_FALLING","reg=outlaw,raider,gang,club,crime,prison",{"Snow - great, a trail for every dead son of a gun to follow","Snow, great, now they can see our footprints"}},
{"SNOW_FALLING","reg=outlaw,raider,gang,club,crime,prison|tmp=predator",{"Snow, anything we leave behind is going to show"}},
{"SNOW_FALLING","world=road",{"If it keeps this up we won't see the road by morning"}},
{"SNOW_FALLING","reg=civilian,family,worker|tmp=fresh|mood=sad",{"Snow day used to mean no school and hot cocoa","We always built a snowman, always, my brother's was crooked"}},
{"SNOW_FALLING","reg=civilian,family,worker|tmp=fresh|mood=warm|world=road",{"Snowball fights in the yard, the whole street, laughing"}},
{"SNOW_FALLING","reg=civilian,family,worker|tmp=fresh|mood=warm",{"It's so pretty, I can't help it, it's pretty"}},
{"SNOW_FALLING","reg=civilian,family,worker|tmp=seasoned|mood=calm",{"Snow hides noise, snow shows tracks, think about that","Wrap up, wet feet freeze faster than dry ones"}},
{"SNOW_FALLING","reg=civilian,family,worker|mood=funny",{"Anyone want to build a snowman? Anyone? Okay, no, fine"}},
{"SNOW_FALLING","reg=law,swat|world=vehicle,road",{"Snow on the road, no sense in a cruiser, even if we had one"}},
{"SNOW_GROUND","",{"Snow's up past my ankles","Every step crunches, can't sneak on this","Wet socks again, always the socks","There's ice under this snow - watch it","Snow's packed hard, feels like walking on gravel","Boots are soaked through - can't win","Crust on top and slush below - worst kind","Somebody's walked here before us - see the prints?","Snow doesn't care who walks on it, takes everybody's print the same","Snow's deep, up to my ankles","Crunch, crunch, every step, too loud","Our tracks lead straight back to us","Ice under the snow, slippery, watch it","White everywhere, it hurts my eyes","Snow's heavy, packed down, hard to walk","Frozen solid, and I'm slipping and sliding"}},
{"SNOW_GROUND","world=road",{"Can't tell where the curb ends and the road starts","Can't tell where the road ends and the ditch begins"}},
{"SNOW_GROUND","world=building",{"The drifts against the houses are taller than the porch steps"}},
{"SNOW_GROUND","reg=civilian,family,worker,rescue",{"Snow makes everything harder, doesn't it?"}},
{"SNOW_GROUND","reg=civilian,family,worker,rescue|tmp=seasoned|world=vehicle",{"Tire tracks in the snow - old ones, nobody's driven this since the storm"}},
{"SNOW_GROUND","reg=law,swat|world=door",{"Those tracks go straight to that door, eyes on it"}},
{"SNOW_GROUND","reg=military,elite|tmp=veteran",{"Prints in the snow - count them, then count again"}},
{"SNOW_GROUND","reg=outlaw,raider,gang,club,crime,prison",{"Dead bodies are under there somewhere, I'd rather not find out","Snow's hiding the dead, watch where you step"}},
{"SNOW_GROUND","reg=civilian,family,worker|mood=sad",{"Snow on the ground, and nobody out playing in it"}},
{"SNOW_GROUND","reg=civilian,family,worker|tmp=seasoned|mood=calm",{"Walk in single file, step where the first person stepped"}},
{"SNOW_GROUND","reg=civilian,family,worker|tmp=seasoned|mood=calm|world=road",{"Brush your tracks, or use the road, snow tells everything"}},
{"SNOW_GROUND","reg=law,swat",{"Snow cover, footprints everywhere, track them, track them back"}},
{"SNOW_GROUND","reg=military,elite",{"Ground snow, tracks visible, assume the enemy sees us"}},
{"SPOT_STRANGER","reg=raider,gang,prison,club",{"Look, over there! Somebody walking around like they own the place!","Hey, you, the one pretending not to see us! Stop!"}},
{"SPOT_STRANGER","reg=raider,outlaw",{"Heads up, we got a live one! Hey! Don't move!"}},
{"SPOT_STRANGER","reg=gang,prison",{"Yo! You! Don't you move a muscle!"}},
{"SPOT_STRANGER","reg=raider,club,outlaw|world=road",{"Well, well, look what wandered off the road - hold it right there!","Stop! This road's got a toll, and you're about to pay it!"}},
{"SPOT_STRANGER","reg=outlaw,crime",{"Hold up, somebody's out there - hey! Stay right where you are!"}},
{"SPOT_STRANGER","reg=raider,gang",{"Fresh one on {street}! Cut 'em off before they run!"}},
{"SPOT_STRANGER","reg=raider,prison,gang|tmp=predator",{"You there! Stop right there, asshole!","Hey! Hey! Stop walking or I start shooting!"}},
{"SPOT_STRANGER","reg=outlaw,crime,raider",{"Somebody's been trailing us - you! Out where I can see you!"}},
{"SPOT_STRANGER","reg=raider,club",{"Company! Spread out, don't let 'em run!","Somebody's here! Stop, you! I want a word!","Oh look, a straggler - stop right there, straggler!"}},
{"SPOT_STRANGER","reg=raider,club|tmp=predator",{"Look at this, a tourist! Hey, tourist, hold it right there!"}},
{"SPOT_STRANGER","role=prisoner",{"Somebody's out there! Could be a guard! No, it ain't - hey, you, freeze!"}},
{"SPOT_STRANGER","reg=prison",{"Hey! I want a word with you! Stop walking!","Nobody's locking me up again! You! Freeze, I swear to God!"}},
{"SPOT_STRANGER","reg=gang|world=road",{"Who's that walking on our street? Hey! You don't just walk here!"}},
{"SPOT_STRANGER","role=gang_member",{"Yo, check it, somebody's lost - hey! You lost? Come here!"}},
{"SPOT_STRANGER","reg=gang",{"This ain't your neighborhood! Stop right there!"}},
{"SPOT_STRANGER","role=gang_boss",{"Somebody's out there - go get 'em - bring 'em to me"}},
{"SPOT_STRANGER","role=biker",{"Somebody's on foot by the bikes! Hey! Get away from those!"}},
{"SPOT_STRANGER","role=biker_boss|world=road",{"We got a stranger on our road - stop that one, I want a word"}},
{"SPOT_STRANGER","role=raider",{"Somebody's here! Stop them. I want a word!"}},
{"SPOT_STRANGER","reg=raider,gang,prison",{"Hey, you! Don't even think about running!","Over here, guys! Somebody's sneaking around! You, freeze!"}},
{"SPOT_STRANGER","role=raider_boss",{"Look alive, somebody's at our edge - hey! Stop where you are!"}},
{"SPOT_STRANGER","reg=raider|tmp=predator",{"Payday's walking our way, boys! Hey, stop!"}},
{"SPOT_STRANGER","role=outlaw",{"Hold it - somebody's there - you! Stop, and keep your hands out"}},
{"SPOT_STRANGER","role=deserter",{"You! Halt! Don't make me do this"}},
{"SPOT_STRANGER","reg=crime",{"Hey, you! Stop a second, we need to talk"}},
{"SPOT_STRANGER","reg=crime,outlaw",{"Stranger! I want a word with you! Stop!","Lookout says we got a walk-up - there! You! Stop!"}},
{"SPOT_STRANGER","reg=raider,club,prison",{"Ain't this our lucky day, hey, you there, stop!","Wake up, boys, we got a visitor! Hey, you, stay put!"}},
{"SPOT_STRANGER","reg=raider,outlaw,club",{"Movement! It's a person, not one of them! Hey! Stop!"}},
{"SPOT_STRANGER","reg=raider,gang,prison,club|tmp=predator",{"Look who's out for a stroll, stop, sweetheart"}},
{"SPOT_STRANGER","reg=club,outlaw,crime",{"Hold it right there, {g:buddy|lady}, you're on private property now!"}},
{"SPOT_STRANGER","reg=raider,prison|tmp=predator",{"Somebody's out there and they ain't dead! Get 'em!"}},
{"SPOT_STRANGER","reg=gang,prison,raider",{"Don't you walk away from me! Stop!"}},
{"SPOT_STRANGER","reg=gang,prison,raider|tmp=predator",{"Hey, genius! Yeah, you! Don't move!"}},
{"SPOT_STRANGER","reg=outlaw,raider,gang,club,crime,prison|hour=21,4",{"Who's out there in the dark? Show yourself! Stop!"}},
{"SPOT_STRANGER","reg=raider,prison,club",{"Well, lookie here, somebody still breathing! Stop right there!"}},
{"SPOT_STRANGER","reg=outlaw,gang,crime,prison",{"Stop! Don't make me chase you in this heat!"}},
{"SPOT_STRANGER","reg=prison,raider|tmp=predator",{"Nice boots on that one - hey! Stop, I want to try 'em on!"}},
{"SPOT_STRANGER","reg=raider|hour=21,4",{"Something's moving out there - don't shine that yet - let it come closer"}},
{"SPOT_STRANGER","reg=raider,outlaw|hour=21,4",{"Heard boots, boots, not them, boots don't shuffle - hey! Stop!"}},
{"SPOT_STRANGER","reg=raider,gang|hour=20,5|world=building",{"There, by the mailbox, that's a {g:man|woman} - hey! You! Stand still!"}},
{"SPOT_STRANGER","reg=raider,prison|hour=20,5",{"Light {him} up! There, there! Don't move!","Stop! We already killed one thing tonight! Don't be the second!"}},
{"SPOT_STRANGER","reg=raider,club|hour=21,4",{"Walking around at night, you stupid or what? HEY!"}},
{"SPOT_STRANGER","reg=raider|tmp=predator|hour=20,5",{"I smelled {him} before I saw {him} - hey! You! Hands out!"}},
{"SPOT_STRANGER","reg=raider,crime|hour=21,4",{"Somebody's here. Stay quiet and watch {him}"}},
{"SPOT_STRANGER","reg=raider,outlaw|hour=20,5",{"Don't run, you run at night out here, you run into them - stop!"}},
{"SPOT_STRANGER","reg=raider|tmp=predator|hour=22,3",{"Ooh, a night owl - come here, night owl - HEY! Stop!"}},
{"SPOT_STRANGER","reg=gang|hour=21,4",{"Yo, somebody out there - cut the lamp - hey! You! Don't move!"}},
{"SPOT_STRANGER","reg=gang,crime|hour=22,3",{"That ain't one of ours, nobody of ours is out this hour - stop!"}},
{"SPOT_STRANGER","reg=gang|hour=0,4",{"Hey! You out walking at two in the morning? Stand still, {g:man|lady}"}},
{"SPOT_STRANGER","reg=gang,prison|hour=21,4",{"Somebody creeping, somebody always creeping at night - freeze!"}},
{"SPOT_STRANGER","reg=club|hour=20,5|world=road",{"Kill the headlight, somebody's on the road - hey! Hold up there!"}},
{"SPOT_STRANGER","reg=club,crime|hour=21,4",{"Hear that gravel? That's a {g:man|woman} - hey, friend - stop walking, please"}},
{"SPOT_STRANGER","reg=club,outlaw|hour=21,4|world=road",{"Nobody walks this road after dark by accident - hold it right there"}},
{"SPOT_STRANGER","reg=club,crime|hour=20,5",{"Stop where you are, you don't want to be moving out here tonight"}},
{"SPOT_STRANGER","reg=crime|tmp=veteran|hour=22,3|world=road",{"A {g:man|woman} on the road at this hour is desperate or paid - stop there"}},
{"SPOT_STRANGER","reg=crime|hour=21,4",{"Hold it right there, nobody's out at night for a good reason","Stand still and stay in the light, that's all I'm asking at this hour"}},
{"SPOT_STRANGER","reg=crime,outlaw|hour=20,5",{"Stop walking, I can't see your hands, and that makes me nervous"}},
{"SPOT_STRANGER","reg=prison|hour=21,4",{"Somebody out there! I hear {him}! HEY! STOP!"}},
{"SPOT_STRANGER","reg=prison|hour=20,5",{"Eight years of nights, I know a {g:man|woman} moving in the dark - freeze!"}},
{"SPOT_STRANGER","reg=prison,raider|hour=22,3",{"Who's that?! Don't move! Say something or don't move!"}},
{"SPOT_STRANGER","reg=outlaw|hour=21,4",{"Hold it, I've got a light and I ain't afraid to use it - stop there"}},
{"SPOT_STRANGER","reg=outlaw|tmp=seasoned|hour=22,3",{"Stop, nobody sneaks up on a {g:man|woman} who don't sleep - stand still"}},
{"SPOT_STRANGER","reg=outlaw|tmp=seasoned|hour=20,5",{"Quit walking, eyes are bad but my ears work fine"}},
{"SPOT_STRANGER","reg=outlaw,club|hour=21,4",{"Stop, it's dark and I'm jumpy, don't give me a reason"}},
{"SPOT_STRANGER","reg=raider,gang,prison|hour=20,5",{"You hear that? Somebody's out in it - hey! Stop!"}},
{"SPOT_STRANGER","reg=crime,club,raider|hour=21,4",{"I see someone. Don't call out yet"}},
